-- 2026-09-17 - the diesel fleet: 4718 locos, our first
--
-- SOURCE: DSL LOCO DATABASE.csv plus the shed-code tables, both supplied by the
-- operator on 2026-09-17. That is ALL the data that exists for diesels - number,
-- class and shed. No commission date, no converter, no hotel load.
--
-- WHY IT MATTERS
-- div_locos held 13,825 locos and not one diesel, yet WDP4D diesels work BB
-- trains daily: 23 loco numbers appear on our sheets with no master row at all,
-- 16 of them in this file, mostly Kalyan-based. Until now the electric database
-- could not cover them - it is the ELECTRIC loco database.
--
-- SHED CODES: the loco file carries STATION codes (Kalyan (KYN)) while our
-- master carries SHED codes (KYNE, PADX). They are resolved through the
-- operator's shed-code tables, preferring the DIESEL shed at a location -
-- Kalyan diesel is KYDX, not KYNE; Pune diesel is PADX, which is what our
-- diesel workings already expect.
--
-- Where a location has only an ELECTRIC shed in those tables (183 locos at
-- Malda Town, Bokaro, Santragachi and the like) the source's own code is kept
-- instead. Filing a diesel in an electric shed would be worse than a code we
-- cannot expand.
--
-- hotel_load_oem is deliberately left NULL for every row: diesels are not HOG
-- fitted, and NULL is how that is said here - any text reads as HOG-capable.
--
-- traction_type 'Diesel' is used for the first time; the column has always
-- allowed it (enum Electric/Diesel/Dual) so no schema change is needed.
--
-- One duplicate row in the source (69081, listed twice identically) is dropped.
-- 2 locos get no shed: a museum piece, a works, and one blank row.
--
-- INSERT IGNORE, so a re-run is a no-op. No loco number here collides with the
-- existing electric fleet - checked.

-- Step 1 - before.
SELECT traction_type, COUNT(*) AS locos FROM div_locos GROUP BY traction_type;

-- Step 2 - insert.
INSERT IGNORE INTO div_locos
  (loco_number, loco_type, traction_type, railway_zone, home_shed, status,
   data_source, entered_by)
