-- Step 3 - verify.
SELECT traction_type, COUNT(*) AS locos FROM div_locos GROUP BY traction_type;
SELECT COUNT(*) AS added FROM div_locos WHERE entered_by = 'dsl-sheet-2026-09-17';
SELECT home_shed, COUNT(*) AS locos FROM div_locos
WHERE entered_by = 'dsl-sheet-2026-09-17' GROUP BY home_shed ORDER BY locos DESC LIMIT 10;
SELECT COUNT(*) AS any_diesel_marked_hog FROM div_locos
WHERE traction_type = 'Diesel' AND hotel_load_oem IS NOT NULL;

-- How many locos on our sheets are still unknown to the master? (was 23)
SELECT COUNT(DISTINCT l.actual_loco_no) AS still_unregistered
FROM div_loco_link_log l LEFT JOIN div_locos dl ON dl.loco_number = l.actual_loco_no
WHERE l.actual_loco_no REGEXP '^[0-9]{4,6}$' AND dl.loco_number IS NULL;

